package org.brightstats.desktop;
import java.util.*;
import java.nio.file.Path;
import com.google.gson.*;
import javafx.concurrent.Task;
import javafx.geometry.Insets;
import javafx.scene.control.*;
import javafx.scene.layout.*;
import javafx.stage.Window;
import org.brightstats.data.*;
import org.brightstats.data.DataPreparation.*;
import org.brightstats.data.DataTransforms.*;

/** Fixed, declarative operations; no expression interpreter or external executable. */
final class DataTransformDialog {
    private static final Gson JSON=new GsonBuilder().serializeNulls().setPrettyPrinting().setStrictness(Strictness.STRICT).create();
    private final Dialog<Specification> dialog=new Dialog<>();private final ComboBox<Operation> operation=new ComboBox<>();private final ListView<String> sources=new ListView<>();private final TextField output=new TextField(),factor=new TextField("1"),offset=new TextField("0"),lower=new TextField("1"),upper=new TextField("5"),missingLabel=new TextField("[missing]");private final TextArea levels=new TextArea("[]"),mapping=new TextArea("{}");private final ComboBox<String> reference=new ComboBox<>();private final CheckBox missingCategory=new CheckBox("Use an explicit missing category");private final Label status=UiAppearance.label("");private final GridPane options=new GridPane();private final JsonObject history;private final List<String> currentNames;private final double[][] current;private final Raw raw;private final Settings settings;private final List<Column> definitions;private Task<DataTransforms.Result> preview;
    private DataTransformDialog(Window owner,JsonObject history,List<String> names,double[][] values){this.history=history==null?null:history.deepCopy();currentNames=List.copyOf(names);current=org.brightstats.stats.Matrices.copy(values);if(history!=null){var source=ImportHistory.read(history);raw=source.raw();settings=source.settings();definitions=source.definitions();}else{List<List<String>> rows=new ArrayList<>();for(var row:values){List<String> cells=new ArrayList<>();for(double value:row)cells.add(Double.toString(value));rows.add(cells);}raw=new Raw(names,rows);settings=new Settings(',',Decimal.DOT,"",Missing.REQUIRE_COMPLETE);definitions=names.stream().map(name->new Column(name,Kind.NUMERIC)).toList();}dialog.initOwner(owner);dialog.setTitle("Transform and recode original data");dialog.setResizable(true);dialog.getDialogPane().getButtonTypes().addAll(ButtonType.OK,ButtonType.CANCEL);operation.getItems().setAll(Operation.values());sources.getItems().setAll(definitions.stream().map(Column::name).toList());sources.getSelectionModel().setSelectionMode(SelectionMode.MULTIPLE);sources.setPrefSize(260,360);sources.setAccessibleText("Original source columns; use Ctrl or Shift for multiple sources");levels.setPrefRowCount(5);mapping.setPrefRowCount(6);reference.setConverter(new javafx.util.StringConverter<>(){public String toString(String value){return value==null||value.isEmpty()?"No reference (all levels)":value;}public String fromString(String value){return value;}});Button populate=UiAppearance.button("Read categories from source");populate.setOnAction(event->{try{populate();}catch(RuntimeException problem){status.setText(problem.getMessage());}});Button inspect=UiAppearance.button("Preview new columns");inspect.setOnAction(event->preview());Label guide=UiAppearance.label("Append new columns while retaining existing numeric values, model bindings and source rows. Operations run on original source cells before the current missing-value policy. Category matching uses trimmed source text exactly. No fitted cohort normalization or arbitrary expression execution is used.");guide.setWrapText(true);guide.setMaxWidth(850);options.setHgap(10);options.setVgap(8);HBox body=new HBox(15,new VBox(6,UiAppearance.label("Original source columns (Ctrl/Shift to select)"),sources),new VBox(8,options,populate,inspect));VBox content=new VBox(12,guide,new HBox(10,UiAppearance.label("Operation"),operation),body,status);content.setPadding(new Insets(14));status.setWrapText(true);status.setMaxWidth(850);dialog.getDialogPane().setContent(content);operation.valueProperty().addListener((o,a,b)->render());sources.getSelectionModel().getSelectedItems().addListener((javafx.collections.ListChangeListener<String>)change->{suggest();});missingCategory.selectedProperty().addListener((o,a,b)->{if(operation.getValue()==Operation.DUMMY||operation.getValue()==Operation.RECODE)try{populate();}catch(RuntimeException ignored){}});operation.setValue(Operation.SQUARE);sources.getSelectionModel().selectFirst();dialog.getDialogPane().lookupButton(ButtonType.OK).addEventFilter(javafx.event.ActionEvent.ACTION,event->{try{read();}catch(RuntimeException problem){status.setText(problem.getMessage());event.consume();}});dialog.setResultConverter(button->button==ButtonType.OK?read():null);dialog.setOnHidden(event->{if(preview!=null)preview.cancel(true);});}
    private void render(){options.getChildren().clear();int row=0;field(row++,"New name / dummy prefix",output);var selected=operation.getValue();if(selected==Operation.DUMMY){field(row++,"Complete levels (JSON array)",levels);field(row++,"Reference category",reference);}if(selected==Operation.RECODE)field(row++,"Explicit label → number mapping (JSON)",mapping);if(selected==Operation.DUMMY||selected==Operation.RECODE){options.add(missingCategory,0,row++,2,1);field(row++,"Missing category label",missingLabel);}if(selected==Operation.AFFINE){field(row++,"Fixed multiplier",factor);field(row++,"Fixed offset",offset);}if(selected==Operation.REVERSE){field(row++,"Declared minimum",lower);field(row++,"Declared maximum",upper);}suggest();}
    private void field(int row,String text,Control control){options.add(UiAppearance.label(text),0,row);options.add(control,1,row);control.setAccessibleText(text);control.setMaxWidth(430);}
    private void suggest(){if(operation.getValue()==null||sources.getSelectionModel().getSelectedItems().isEmpty())return;String base=sources.getSelectionModel().getSelectedItems().getFirst()+"_"+operation.getValue().name().toLowerCase(Locale.ROOT);String name=base;int suffix=2;Set<String> existing=new HashSet<>(sources.getItems());while(existing.contains(name))name=base+suffix++;output.setText(name);if(operation.getValue()==Operation.DUMMY||operation.getValue()==Operation.RECODE)try{populate();}catch(RuntimeException problem){status.setText(problem.getMessage());}}
    private void populate(){var selected=sources.getSelectionModel().getSelectedItems();if(selected.size()!=1)throw new IllegalArgumentException("Choose one source for categories.");int column=sources.getItems().indexOf(selected.getFirst());Set<String> found=new TreeSet<>();boolean missing=false;for(var row:raw.rows()){String value=row.get(column);if(DataPreparation.missing(value,settings))missing=true;else found.add(value.strip());}String label=missingLabel.getText().strip();if(missingCategory.isSelected()){if(label.isBlank())throw new IllegalArgumentException("Name the missing category.");if(found.contains(label)){String base=label;int suffix=2;while(found.contains(label))label=base+suffix++;missingLabel.setText(label);}found.add(label);}if(found.size()>1000)throw new IllegalArgumentException("Use at most 1,000 recode categories or 64 dummy levels.");levels.setText(JSON.toJson(found));String previous=reference.getValue();reference.getItems().setAll("");reference.getItems().addAll(found);reference.setValue(previous!=null&&reference.getItems().contains(previous)?previous:found.isEmpty()?"":found.iterator().next());JsonObject codes=new JsonObject();int index=0;for(String value:found)codes.addProperty(value,index++);mapping.setText(JSON.toJson(codes));status.setText(missing&&!missingCategory.isSelected()?"Missing category cells remain missing and follow the current preparation policy.":"Generated level order/codes are proposals; review reference and numeric coding before applying.");}
    private Specification read(){if(output.getText().isBlank())throw new IllegalArgumentException("Name the new output or dummy prefix.");var selected=operation.getValue();List<String> inputs=List.copyOf(sources.getSelectionModel().getSelectedItems());List<String> outputs=new ArrayList<>(),categories=new ArrayList<>();Map<String,Double> recodes=new LinkedHashMap<>();String ref="";if(selected==Operation.DUMMY){if(levels.getText().length()>65536)throw new IllegalArgumentException("Category schema is too large.");for(var value:JSON.fromJson(levels.getText(),JsonArray.class)){if(!value.isJsonPrimitive()||!value.getAsJsonPrimitive().isString())throw new IllegalArgumentException("Dummy levels must be text labels.");categories.add(value.getAsString());}ref=reference.getValue()==null?"":reference.getValue();int index=0;for(String value:categories)if(!value.equals(ref)){String part=value.replaceAll("[^\\p{L}\\p{N}_-]","_");if(part.length()>50)part=part.substring(0,50);outputs.add(output.getText().strip()+"_"+(++index)+"_"+part);}}else outputs.add(output.getText());if(selected==Operation.RECODE){if(mapping.getText().length()>65536)throw new IllegalArgumentException("Recode schema is too large.");for(var value:JSON.fromJson(mapping.getText(),JsonObject.class).entrySet()){if(!value.getValue().isJsonPrimitive()||!value.getValue().getAsJsonPrimitive().isNumber())throw new IllegalArgumentException("Recode targets must be numeric.");recodes.put(value.getKey(),value.getValue().getAsDouble());}}return new Specification(selected,inputs,outputs,categories,ref,recodes,selected==Operation.AFFINE?Double.valueOf(factor.getText()):null,selected==Operation.AFFINE?Double.valueOf(offset.getText()):null,selected==Operation.REVERSE?Double.valueOf(lower.getText()):null,selected==Operation.REVERSE?Double.valueOf(upper.getText()):null,missingCategory.isSelected()&&(selected==Operation.DUMMY||selected==Operation.RECODE)?missingLabel.getText():null);}
    private void preview(){try{var specification=read();if(preview!=null)preview.cancel(true);Task<DataTransforms.Result> task=new Task<>(){protected DataTransforms.Result call(){return DataTransforms.append(history,currentNames,current,specification);}};preview=task;status.setText("Preparing a source-preserving preview...");task.setOnSucceeded(event->{if(preview!=task)return;var result=task.getValue();double[][] values=result.prepared().values();int start=currentNames.size();StringBuilder text=new StringBuilder(result.prepared().columns().size()-start+" new columns; existing values/source rows retained. First new values: ");for(int i=0;i<Math.min(5,values.length);i++)text.append(Arrays.toString(Arrays.copyOfRange(values[i],start,values[i].length))).append(' ');status.setText(text.toString());});task.setOnFailed(event->{if(preview==task)status.setText(task.getException().getMessage());});Thread.ofVirtual().start(task);}catch(RuntimeException problem){status.setText(problem.getMessage());}}
    static Optional<Specification> show(Window owner,JsonObject history,List<String> names,double[][] values){return new DataTransformDialog(owner,history,names,values).dialog.showAndWait();}
    static Specification smoke(Window owner,JsonObject history,List<String> names,double[][] values,Operation operation,Path image)throws Exception{var editor=new DataTransformDialog(owner,history,names,values);editor.dialog.show();editor.operation.setValue(operation);editor.sources.getSelectionModel().clearSelection();editor.sources.getSelectionModel().select(operation==Operation.DUMMY?"Group":"X");if(operation==Operation.DUMMY){editor.missingCategory.setSelected(true);editor.populate();editor.reference.setValue("A");}else editor.output.setText("X_squared");String valid=editor.output.getText();editor.output.setText("");((Button)editor.dialog.getDialogPane().lookupButton(ButtonType.OK)).fire();if(!editor.dialog.isShowing()||editor.status.getText().isBlank())throw new AssertionError("Invalid transform dialog accepted");editor.output.setText(valid);var result=editor.read();editor.dialog.getDialogPane().applyCss();editor.dialog.getDialogPane().layout();java.nio.file.Files.deleteIfExists(image);GraphicExport.png(image,editor.dialog.getDialogPane(),1);editor.dialog.setResult(null);editor.dialog.close();return result;}
}
